using System;using System.Linq;using System.Drawing;using System.Windows.Forms;namespace ServiceTool{internal static class UserScreenshotRegressionTests{static System.Collections.Generic.IEnumerable<Control> Walk(Control p){foreach(Control c in p.Controls){yield return c;foreach(var x in Walk(c))yield return x;}}[STAThread]static int Main(){try{int n=0;foreach(bool dark in new[]{true,false}){foreach(string appId in new[]{"rudesktop","anydesk"})using(var f=new SoftwareRemoteDialog(ThemePalette.Create(dark),null,appId,false)){f.Show();for(int i=0;i<15;i++)Application.DoEvents();f.UpdateKeyboardState("ru",false);var a=Walk(f).ToArray();var notice=a.OfType<Label>().Single(x=>x.Name=="passwordNotice");var cancel=(Control)f.CancelButton;var ok=(Control)f.AcceptButton;if(Math.Abs(notice.PointToScreen(Point.Empty).X-cancel.PointToScreen(Point.Empty).X)>1)throw new Exception("Notice edge");if(cancel.Width!=ok.Width&&Math.Abs(cancel.Width-ok.Width)>1)throw new Exception("Equal buttons");if(cancel.Width<f.ClientSize.Width*.4)throw new Exception("Buttons shrunk");n+=3;Save(f,"password-"+appId+"-"+dark);}using(var f=new ManagerHub()){f.SetTheme(dark,false);f.Show();for(int i=0;i<15;i++)Application.DoEvents();f.Enabled=false;if(!Walk(f).OfType<InheritedThemeLabel>().Any())throw new Exception("Theme labels missing");n++;Save(f,"disabled-launcher-"+dark);f.Enabled=true;}}Console.WriteLine("PASS "+n+" user screenshot regression checks, both themes.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}static void Save(Form f,string name){using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,name+".png"));}}}}